VALUES (NULL, 'dpa', 'standard_dpa', 'ข้อตกลงการประมวลผลข้อมูลส่วนบุคคล (DPA) มาตรฐาน / Standard Data Processing Agreement', 'mul',
$j${"th": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[ร่าง — ข้อความตัวอย่างนี้ต้องได้รับการทบทวนและอนุมัติจากฝ่ายกฎหมายก่อนใช้งานจริง]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "คู่สัญญา"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ข้อตกลงฉบับนี้ทำขึ้นระหว่าง "}, {"type": "mergeField", "attrs": {"key": "org_name_th"}}, {"type": "text", "text": " (\"ผู้ควบคุมข้อมูลส่วนบุคคล\") และ [ชื่อผู้ประมวลผล] (\"ผู้ประมวลผลข้อมูลส่วนบุคคล\") ตามมาตรา 40 แห่งพระราชบัญญัติคุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ขอบเขตและคำสั่งในการประมวลผล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลตกลงประมวลผลข้อมูลส่วนบุคคลเฉพาะตามคำสั่งที่เป็นลายลักษณ์อักษรของผู้ควบคุมข้อมูลส่วนบุคคลเท่านั้น ตามวัตถุประสงค์ ประเภทข้อมูล และระยะเวลาที่ระบุไว้ในภาคผนวก [โปรดระบุรายละเอียดการประมวลผลในภาคผนวก]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การรักษาความลับ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลต้องรักษาความลับของข้อมูลส่วนบุคคลและกำหนดให้บุคคลที่เกี่ยวข้องรักษาความลับเช่นเดียวกัน"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "มาตรการความปลอดภัยของข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลต้องจัดให้มีมาตรการรักษาความมั่นคงปลอดภัยที่เหมาะสมตามมาตรา 37(2) และประกาศมาตรการความปลอดภัย พ.ศ. 2565 [โปรดระบุมาตรการที่ใช้]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การแจ้งเหตุละเมิดข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลต้องแจ้งเหตุการละเมิดข้อมูลส่วนบุคคลให้ผู้ควบคุมข้อมูลส่วนบุคคลทราบโดยไม่ชักช้าภายใน [โปรดระบุระยะเวลา] นับแต่ทราบเหตุ"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลช่วง (Sub-processor)"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลจะมอบหมายให้ผู้ประมวลผลข้อมูลส่วนบุคคลช่วงดำเนินการแทนได้เฉพาะเมื่อได้รับความยินยอมล่วงหน้าจากผู้ควบคุมข้อมูลส่วนบุคคล และต้องผูกพันผู้ประมวลผลข้อมูลส่วนบุคคลช่วงด้วยข้อกำหนดเดียวกันกับข้อตกลงฉบับนี้"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ความช่วยเหลือในการตอบคำขอใช้สิทธิของเจ้าของข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ประมวลผลข้อมูลส่วนบุคคลต้องให้ความช่วยเหลือผู้ควบคุมข้อมูลส่วนบุคคลในการตอบสนองต่อคำขอใช้สิทธิของเจ้าของข้อมูลส่วนบุคคลตามที่กฎหมายกำหนด"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การคืนหรือทำลายข้อมูลส่วนบุคคลเมื่อสิ้นสุดข้อตกลง"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เมื่อสิ้นสุดข้อตกลงนี้ ผู้ประมวลผลข้อมูลส่วนบุคคลต้องคืนหรือทำลายข้อมูลส่วนบุคคลทั้งหมดตามที่ผู้ควบคุมข้อมูลส่วนบุคคลกำหนด เว้นแต่กฎหมายกำหนดให้ต้องเก็บไว้ต่อไป"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "สิทธิในการตรวจสอบของผู้ควบคุมข้อมูล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "ผู้ควบคุมข้อมูลส่วนบุคคลมีสิทธิตรวจสอบการปฏิบัติตามข้อตกลงนี้ของผู้ประมวลผลข้อมูลส่วนบุคคลตามความเหมาะสม"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "การโอนข้อมูลส่วนบุคคลไปต่างประเทศ"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "หากมีการโอนข้อมูลส่วนบุคคลไปต่างประเทศ ผู้ประมวลผลข้อมูลส่วนบุคคลต้องปฏิบัติตามมาตรา 28 และ 29 และจัดให้มีมาตรการคุ้มครองที่เหมาะสม [โปรดระบุประเทศปลายทางและมาตรการคุ้มครอง]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "ข้อมูลติดต่อเจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "เจ้าหน้าที่คุ้มครองข้อมูลส่วนบุคคล: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " อีเมล "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}, "en": {"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "[DRAFT — this sample text must be reviewed and approved by Legal before real use]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Parties"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "This agreement is made between "}, {"type": "mergeField", "attrs": {"key": "org_name_en"}}, {"type": "text", "text": " (the \"Controller\") and [processor name] (the \"Processor\") under section 40 of the Personal Data Protection Act B.E. 2562"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Scope and processing instructions"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Processor shall process personal data only on the Controller's written instructions, for the purposes, data categories and duration set out in the annex. [Please specify processing details in the annex]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Confidentiality"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Processor shall keep personal data confidential and require anyone involved in processing to do the same."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Security measures"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Processor shall implement appropriate security measures under section 37(2) and the 2022 Security Measures Notification. [Please specify the measures used]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Personal data breach notification"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Processor shall notify the Controller of a personal data breach without delay, within [please specify a timeframe] of becoming aware of it."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Sub-processors"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Processor may only engage a sub-processor with the Controller's prior consent, and shall bind the sub-processor to the same terms as this agreement."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Assistance with data subject rights requests"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Processor shall assist the Controller in responding to data subject rights requests as required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Return or destruction of personal data on termination"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "On termination of this agreement, the Processor shall return or destroy all personal data as directed by the Controller, unless retention is required by law."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Controller's audit rights"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "The Controller may audit the Processor's compliance with this agreement as reasonably appropriate."}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Cross-border transfer of personal data"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Where personal data is transferred abroad, the Processor shall comply with sections 28 and 29 and implement appropriate safeguards. [Please specify the destination country and safeguards]"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "Data Protection Officer contact"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Data Protection Officer: "}, {"type": "mergeField", "attrs": {"key": "dpo_name"}}, {"type": "text", "text": " e-mail "}, {"type": "mergeField", "attrs": {"key": "dpo_email"}}]}]}}$j$::jsonb, 1, 'published');

